const inputs = $input.all();
const out = [];
for (let i = 0; i < inputs.length; i++) {
  const j = inputs[i].json || {};
  const bin = inputs[i].binary || {};
  const h = j.headers || {};
  let from = "";
  if (typeof j.from === "string") { from = j.from; }
  else if (j.from && j.from.text) { from = j.from.text; }
  else if (j.from && j.from.value && j.from.value[0]) { from = j.from.value[0].address || ""; }
  else { from = h.from || ""; }
  const subject = j.subject || h.subject || "(no subject)";
  const body = String(j.text || j.snippet || "").replace(/\s+/g, " ").trim().slice(0, 1500);
  const receivedAt = j.date || h.date || "";
  const keys = Object.keys(bin).filter(function (k) { return k.indexOf("attachment_") === 0; });
  for (let n = 0; n < keys.length; n++) {
    const b = bin[keys[n]];
    out.push({
      json: {
        messageId: j.id || "",
        from: from,
        subject: subject,
        bodyText: body,
        receivedAt: receivedAt,
        originalFilename: b.fileName || "unnamed",
        mimeType: b.mimeType || "",
        fileSize: b.fileSize || ""
      },
      binary: { file: b },
      pairedItem: { item: i }
    });
  }
}
return out;

