const RULES = {
  SUPPLIER_INVOICE: { folder: "01 Supplier Invoices", label: "Invoice" },
  DELIVERY_DOCKET:  { folder: "02 Delivery Dockets", label: "Docket" },
  COMPLIANCE:       { folder: "03 Compliance & Permits", label: "Compliance" },
  UTILITY_BILL:     { folder: "04 Utility Bills", label: "Utility" }
};
const REVIEW_FOLDER = "99 Unsorted for Review";
const MIN_CONFIDENCE = 0.7;

const source = $("Split Attachments").all();
const results = $input.all();
const out = [];

for (let i = 0; i < results.length; i++) {
  const raw = results[i].json || {};
  const ai = (raw.output && typeof raw.output === "object") ? raw.output : raw;
  const meta = source[i].json;
  const binary = source[i].binary;

  const declared = String(ai.docType || "UNKNOWN").toUpperCase();
  const confidence = Number(ai.confidence);
  const scored = isFinite(confidence) ? confidence : 0;
  const recognised = Object.prototype.hasOwnProperty.call(RULES, declared);

  let route = "UNSORTED";
  let reviewReason = "";
  if (!recognised) { reviewReason = "Type came back as " + declared; }
  else if (scored < MIN_CONFIDENCE) { reviewReason = "Confidence " + scored.toFixed(2) + " is under the " + MIN_CONFIDENCE + " threshold"; }
  else { route = declared; }

  const rule = route === "UNSORTED" ? { folder: REVIEW_FOLDER, label: "Review" } : RULES[route];

  const original = String(meta.originalFilename || "unnamed");
  const dot = original.lastIndexOf(".");
  const ext = dot > 0 ? original.slice(dot + 1).toLowerCase() : "pdf";

  let docDate = String(ai.docDate || "");
  if (!/^\d{4}-\d{2}-\d{2}$/.test(docDate)) {
    const fallback = new Date(meta.receivedAt || Date.now());
    docDate = isNaN(fallback.getTime()) ? "undated" : fallback.toISOString().slice(0, 10);
  }

  const vendorSlug = String(ai.vendor || "Unknown").trim().replace(/&/g, "and").replace(/[^A-Za-z0-9]+/g, "-").replace(/^-+|-+$/g, "") || "Unknown";
  const numberRaw = String(ai.docNumber || "NONE").trim();
  const numberSlug = numberRaw.replace(/[^A-Za-z0-9-]+/g, "-").replace(/^-+|-+$/g, "");

  let newFilename;
  if (route === "UNSORTED") {
    newFilename = docDate + "_NEEDS-REVIEW_" + original;
  } else if (numberRaw === "NONE" || numberSlug === "") {
    newFilename = docDate + "_" + vendorSlug + "_" + rule.label + "." + ext;
  } else {
    newFilename = docDate + "_" + vendorSlug + "_" + rule.label + "_" + numberSlug + "." + ext;
  }

  out.push({
    json: {
      route: route,
      folderName: rule.folder,
      newFilename: newFilename,
      originalFilename: original,
      docType: declared,
      vendor: String(ai.vendor || "Unknown"),
      docNumber: numberRaw,
      docDate: docDate,
      amount: String(ai.amount || "NONE"),
      confidence: scored,
      reasoning: String(ai.reasoning || ""),
      reviewReason: reviewReason,
      fromAddress: String(meta.from || ""),
      subject: String(meta.subject || ""),
      messageId: String(meta.messageId || "")
    },
    binary: binary,
    pairedItem: { item: i }
  });
}

return out;

const rules = $('Apply Filing Rules').all();
const byName = {};
for (let i = 0; i < rules.length; i++) { byName[rules[i].json.newFilename] = rules[i].json; }

const stamp = $now.toFormat('yyyy-MM-dd HH:mm');
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const d = items[i].json || {};
  const r = byName[d.name] || {};
  out.push({
    json: {
      'Filed At': stamp,
      'Document Type': r.docType || '',
      'Vendor': r.vendor || '',
      'Document Number': r.docNumber || '',
      'Document Date': r.docDate || '',
      'Amount': r.amount || '',
      'Original Filename': r.originalFilename || '',
      'Filed As': d.name || '',
      'Folder': r.folderName || '',
      'Confidence': r.confidence === undefined ? '' : r.confidence,
      'Why': r.reviewReason ? r.reviewReason : (r.reasoning || ''),
      'From': r.fromAddress || '',
      'Drive Link': d.webViewLink || ''
    }
  });
}

return out;
